@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]

<PageTitle>Track Shipment - @TrackingNumber</PageTitle>

<h2>📦 Shipment Tracking</h2>

@if (isLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning mt-3">
        <strong>Not found.</strong> No shipment matches tracking number <code>@TrackingNumber</code>.
        <a href="/" class="alert-link">Try again</a>.
    </div>
}
else
{
    <div class="card shadow-sm mt-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @shipment.StatusBadgeClass">@shipment.StatusDisplay</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAt.ToString("MMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Delivered On</dt>
                            <dd>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy 'at' h:mm tt")</dd>
                        }
                    </dl>
                </div>
            </div>

            <!-- Progress tracker -->
            <h6 class="mt-3">Shipment Progress</h6>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @ProgressBarClass" role="progressbar"
                     style="width: @ProgressPercent%;" aria-valuenow="@ProgressPercent"
                     aria-valuemin="0" aria-valuemax="100">
                    @shipment.StatusDisplay
                </div>
            </div>
        </div>
    </div>

    <div class="mt-3">
        <a href="/" class="btn btn-outline-secondary">← Track another shipment</a>
    </div>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private ShipmentDto? shipment;
    private bool isLoading = true;

    protected override async Task OnParametersSetAsync()
    {
        isLoading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        isLoading = false;
    }

    private int ProgressPercent => shipment?.Status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };

    private string ProgressBarClass => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>📋 Dispatcher Dashboard</h2>

<div class="row mb-3 g-2">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, recipient..."
               @bind="searchTerm" @bind:event="oninput" @onkeydown="HandleSearchKeyDown" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@FormatStatus(status)</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">
            🔍 Search
        </button>
    </div>
</div>

@if (isLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @s.StatusBadgeClass">@s.StatusDisplay</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width: auto;"
                                            @onchange="e => UpdateStatus(s, e)">
                                        <option value="" disabled selected>Change…</option>
                                        @foreach (var status in GetAvailableStatuses(s.Status))
                                        {
                                            <option value="@status">@FormatStatus(status)</option>
                                        }
                                    </select>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @shipments.Count shipment(s)</p>
}

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert @statusMessageClass alert-dismissible fade show mt-2" role="alert">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> shipments = [];
    private string searchTerm = "";
    private string statusFilter = "";
    private bool isLoading = true;
    private string? statusMessage;
    private string statusMessageClass = "alert-success";

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetShipmentsAsync(
            string.IsNullOrWhiteSpace(statusFilter) ? null : statusFilter,
            string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm);
        isLoading = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && Enum.TryParse<ShipmentStatus>(val, out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                statusMessage = $"Shipment {shipment.TrackingNumber} updated to {updated.StatusDisplay}.";
                statusMessageClass = "alert-success";
                await LoadShipments();
            }
            else
            {
                statusMessage = $"Failed to update shipment {shipment.TrackingNumber}.";
                statusMessageClass = "alert-danger";
            }
        }
    }

    private void HandleSearchKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            _ = LoadShipments();
    }

    private static IEnumerable<ShipmentStatus> GetAvailableStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };
}

